def mp(x1, x2, w1, w2, b, theta):
    z = w1 * x1 + w2 * x2 + b
    return 1 if z >= theta else 0

rows = [(0, 0), (0, 1), (1, 0), (1, 1)]
for x1, x2 in rows:
    print(mp(x1, x2, 1, 1, 0, 2))
for x1, x2 in rows:
    print(mp(x1, x2, 1, 1, 0, 1))
for x1 in (0, 1):
    print(mp(x1, 0, -1, 0, 0, 0))
